export const paymentNoEffects={financial_changed:false,folio_changed:false,security_deposit_changed:false,revenue_changed:false,taxes_changed:false,money_moved:false} as const;
export const paymentAssurance={mode:'operator_record_information',processor_verified:false,settlement_verified:false,cash_counted:false,invoice_issued:false} as const;
