export type PaymentReviewed={schema_version:1;outcome:'reviewed';action:'save_payment_record_review';tenant_id:string;property_id:string;reservation_id:string;entry_id:string;request_id:string;command:PaymentCommand;review:PaymentReview;expected_version:number;version:number;financial_effects:typeof paymentNoEffects;assurance:typeof paymentAssurance;replayed:boolean};
