export type PaymentPending={schema_version:1;actor_id:string;tenant_id:string;property_id:string;reservation_id:string;entry_id:string;request_id:string;command:PaymentCommand;reviewed_source:Pick<ReviewSource,'reservation_id'|'id'|'kind'|'amount_minor'|'currency'|'reference'|'target_entry_id'|'recorded_at'>;retirement_reason:string|null};
